VERSION = "0.1.11"
AI_SOURCE = "// MiniCraft II AI v0.1.10 experimental\n// Galaxy custom script: call MiniCraftAI_Init once from the mod library initialization.\n// This augments melee AI rather than replacing the engine's economy/attack waves.\n// No free units, resources, stat changes, map-wide enemy scans, or queue clearing.\ntrigger mcai_timer = null;\nint mcai_tick = 0;\nint[16] mcai_nextBuild;\nint[16] mcai_nextTrain;\nint[16] mcai_nextExpand;\nint[16] mcai_buildRequests;\nint[16] mcai_trainRequests;\nint[16] mcai_expandRequests;\nint[16] mcai_bankTicks;\nbool mcai_debug = false;\n\nint MCAI_Min(int a, int b) {\n    if (a < b) { return a; }\n    return b;\n}\nint MCAI_Max(int a, int b) {\n    if (a > b) { return a; }\n    return b;\n}\nint MCAI_Count(int p, string kind) {\n    return AITechCount(p, kind, c_techCountQueuedOrBetter);\n}\nint MCAI_Ready(int p, string kind) {\n    return AITechCount(p, kind, c_techCountCompleteOnly);\n}\nint MCAI_Pending(int p, string kind) {\n    return MCAI_Max(0, MCAI_Count(p, kind) - MCAI_Ready(p, kind));\n}\nbool MCAI_Build(int p, int town, string kind, int goal, int priority) {\n    if (mcai_tick < mcai_nextBuild[p] || MCAI_Count(p, kind) >= goal ||\n        MCAI_Pending(p, kind) >= 3 || AIGetInternalBuildQueueCount(p) >= 12) { return false; }\n    AIBuild(p, priority, town, kind, 1, c_makeDefault);\n    mcai_nextBuild[p] = mcai_tick + 1;\n    mcai_buildRequests[p] += 1;\n    return true;\n}\nbool MCAI_Train(int p, int town, string kind, int goal, int batch, int priority) {\n    int count = MCAI_Count(p, kind);\n    if (mcai_tick < mcai_nextTrain[p] || count >= goal ||\n        MCAI_Pending(p, kind) >= batch || AIGetInternalTrainQueueCount(p) >= 32) { return false; }\n    AITrain(p, priority, town, kind, MCAI_Min(batch, goal - count));\n    mcai_nextTrain[p] = mcai_tick + 1;\n    mcai_trainRequests[p] += 1;\n    return true;\n}\nbool MCAI_Expand(int p, int town, string hall, int bases, int workers, int minerals) {\n    int t = 0;\n    int state;\n    if (mcai_tick < mcai_nextExpand[p] || bases >= 8 ||\n        workers < bases * 16 || minerals < 650 || AIGetInternalBuildQueueCount(p) >= 12) { return false; }\n    while (t < c_townMax) {\n        state = AIGetTownState(p, t);\n        if (state == c_townStateClaimed || state == c_townStateBuilding) { return false; }\n        t += 1;\n    }\n    mcai_nextExpand[p] = mcai_tick + 25;\n    AIExpand(p, AIGetTownLocation(p, town), hall);\n    mcai_expandRequests[p] += 1;\n    return true;\n}\nbool MCAI_AirSeen(int p) {\n    return AIKnownUnitCount(p, c_maxPlayers, \"Mutalisk\") > 0 ||\n        AIKnownUnitCount(p, c_maxPlayers, \"Battlecruiser\") > 0 ||\n        AIKnownUnitCount(p, c_maxPlayers, \"Banshee\") > 0 ||\n        AIKnownUnitCount(p, c_maxPlayers, \"Carrier\") > 0 ||\n        AIKnownUnitCount(p, c_maxPlayers, \"VoidRay\") > 0 ||\n        AIKnownUnitCount(p, c_maxPlayers, \"Tempest\") > 0 ||\n        AIKnownUnitCount(p, c_maxPlayers, \"Oracle\") > 0 ||\n        AIKnownUnitCount(p, c_maxPlayers, \"Liberator\") > 0;\n}\nvoid MCAI_Configure(int p, bool banked) {\n    // Absolute scale, never repeatedly multiply the current army.\n    if (banked) { AISetStockArmyDefaultScale(p, 4.0); }\n    else { AISetStockArmyDefaultScale(p, 3.0); }\n    AISetDifficulty(p, c_diffNormalVision, true);\n    AISetDifficulty(p, c_diffOptimizeGas, true);\n    AISetDifficulty(p, c_diffBalancePeonsAcrossBases, true);\n    AISetDifficulty(p, c_diffAutoBuildPrereqs, true);\n    AISetDifficulty(p, c_diffTimeoutMakeRequests, true);\n    AISetDifficulty(p, c_diffFleeWorkers, true);\n    AISetDifficulty(p, c_diffRepairDamage, true);\n    AISetDifficulty(p, c_diffAdvancedRetreatLogic, true);\n    AISetDifficulty(p, c_diffFleeDanger, true);\n    AISetDifficulty(p, c_diffAllowKiting, true);\n    AISetDifficulty(p, c_diffLimitAPM, true);\n    AISetAPM(p, 600);\n}\nvoid MCAI_Economy(int p, int town, string race, int bases, int minerals, int gas, fixed free, fixed made, fixed cap) {\n    string worker = \"SCV\";\n    string hall = \"CommandCenter\";\n    string supply = \"SupplyDepot\";\n    int workers;\n    int goal = MCAI_Min(128, bases * 24);\n    int facilities = MCAI_Min(48, 2 + bases * 6 + minerals / 550);\n    int phase = (mcai_tick + p) % 3;\n    int t = 0;\n    string refinery = \"Refinery\";\n    int spots;\n    int targetGas;\n    if (race == \"Prot\") { worker = \"Probe\"; hall = \"Nexus\"; supply = \"Pylon\"; refinery = \"Assimilator\"; }\n    if (race == \"Zerg\") { worker = \"Drone\"; hall = \"Hatchery\"; supply = \"Overlord\"; refinery = \"Extractor\"; }\n    workers = MCAI_Count(p, worker);\n    // Supply before new producers or army; reserve more as the economy grows.\n    if (made < cap && free < 8.0 + bases * 3 && minerals >= 50 && MCAI_Pending(p, supply) < 3) {\n        if (race == \"Zerg\") { MCAI_Train(p, town, supply, MCAI_Count(p, supply) + 1, 1, c_makePriorityFood); }\n        else { MCAI_Build(p, town, supply, MCAI_Count(p, supply) + 1, c_makePriorityFood); }\n    }\n    if (free >= 1.0 && minerals >= 50 && workers < goal) {\n        MCAI_Train(p, town, worker, goal, MCAI_Min(6, bases * 2), c_makePriorityContinue);\n    }\n    // Use local gas sites instead of queuing refineries at a full main base.\n    if (workers >= 14 && minerals >= 150 && gas < 450 && AIGetTime() >= 65.0) {\n        while (t < c_townMax && mcai_tick >= mcai_nextBuild[p]) {\n            if (AIGetTownState(p, t) == c_townStateEstablished) {\n                spots = AIGetRawGasNumSpots(p, t);\n                targetGas = AIGetBuildingCountInTown(p, t, refinery, c_techCountQueuedOrBetter);\n                if (spots > 0 && targetGas < MCAI_Min(2, spots)) {\n                    MCAI_Build(p, t, refinery, MCAI_Count(p, refinery) + 1, c_makePriorityTown);\n                }\n            }\n            t += 1;\n        }\n    }\n    if (workers >= 12 && free >= 4.0) {\n        if (race == \"Terr\") {\n            if (minerals >= 180 && (phase == 0 || MCAI_Ready(p, \"Barracks\") == 0) && MCAI_Ready(p, \"SupplyDepot\") + MCAI_Ready(p, \"SupplyDepotLowered\") > 0) {\n                MCAI_Build(p, town, \"Barracks\", facilities, c_makePriorityTown);\n            }\n            if (gas >= 80 && minerals >= 180 && (phase == 1 || MCAI_Ready(p, \"Factory\") == 0) && MCAI_Ready(p, \"Barracks\") > 0) {\n                MCAI_Build(p, town, \"Factory\", MCAI_Min(18, bases * 2 + gas / 400), c_makePriorityTown);\n            }\n            if (gas >= 160 && minerals >= 250 && phase == 2 && MCAI_Ready(p, \"Factory\") > 0) {\n                MCAI_Build(p, town, \"Starport\", MCAI_Min(16, bases * 2 + gas / 500), c_makePriorityTown);\n            }\n        } else if (race == \"Prot\") {\n            if (minerals >= 180 && (phase == 0 || (MCAI_Ready(p, \"Gateway\") == 0 && MCAI_Ready(p, \"WarpGate\") == 0)) && MCAI_Ready(p, \"Pylon\") > 0) {\n                // Engine aliases may include WarpGate; do not add an independent target for it.\n                MCAI_Build(p, town, \"Gateway\", facilities, c_makePriorityTown);\n            }\n            if (minerals >= 150 && (MCAI_Ready(p, \"Gateway\") > 0 || MCAI_Ready(p, \"WarpGate\") > 0)) {\n                MCAI_Build(p, town, \"CyberneticsCore\", 1, c_makePriorityTown);\n            }\n            if (gas >= 120 && minerals >= 220 && MCAI_Ready(p, \"CyberneticsCore\") > 0) {\n                if (phase == 1) { MCAI_Build(p, town, \"RoboticsFacility\", MCAI_Min(14, bases + gas / 450), c_makePriorityTown); }\n                if (phase == 2) { MCAI_Build(p, town, \"Stargate\", MCAI_Min(20, bases * 2 + gas / 500), c_makePriorityTown); }\n            }\n        } else if (race == \"Zerg\") {\n            if (minerals >= 140) { MCAI_Build(p, town, \"SpawningPool\", 1, c_makePriorityTown); }\n            if (gas >= 40 && minerals >= 160 && MCAI_Ready(p, \"SpawningPool\") > 0) {\n                MCAI_Build(p, town, \"RoachWarren\", 1, c_makePriorityTown);\n            }\n            if (gas >= 100 && minerals >= 180 && (MCAI_Ready(p, \"Lair\") > 0 || MCAI_Ready(p, \"Hive\") > 0)) {\n                MCAI_Build(p, town, \"HydraliskDen\", 1, c_makePriorityTown);\n            }\n            if (minerals >= 850 && bases >= 2 && MCAI_Ready(p, \"SpawningPool\") > 0) {\n                // Extra hatcheries increase larvae throughput; avoid unlimited macro hatch spam.\n                MCAI_Build(p, town, \"Hatchery\", MCAI_Min(24, bases * 2 + 1 + minerals / 650), c_makePriorityTown);\n            }\n            if (free >= 2.0 && minerals >= 100 && MCAI_Ready(p, \"SpawningPool\") > 0) {\n                MCAI_Train(p, town, \"Queen\", MCAI_Min(24, bases * 2 + 1), 1, c_makePriorityDefense);\n            }\n        }\n    }\n    if (made < cap || free < 4.0) {\n        MCAI_Expand(p, town, hall, bases, workers, minerals);\n    }\n}\nvoid MCAI_Army(int p, int town, string race, int bases, int minerals, int gas, fixed free) {\n    int batch = MCAI_Min(24, MCAI_Min(4 + bases * 4, FixedToInt(free / 2.0)));\n    int goal = MCAI_Min(420, 40 + bases * 48 + minerals / 40);\n    bool air = false;\n    if (batch < 1 || minerals < 100 || mcai_tick < mcai_nextTrain[p]) { return; }\n    air = MCAI_AirSeen(p);\n    // Prefer tech units when available; never block on unavailable prerequisite chains.\n    if (race == \"Terr\") {\n        if (air && gas >= 100 && MCAI_Ready(p, \"Starport\") > 0) {\n            if (MCAI_Train(p, town, \"VikingFighter\", MCAI_Min(28, 4 + bases * 4), MCAI_Min(batch, 6), c_makePriorityDefense)) { return; }\n        }\n        if (!air && gas >= 160 && MCAI_Ready(p, \"FactoryTechLab\") > 0) {\n            if (MCAI_Train(p, town, \"SiegeTank\", MCAI_Min(22, bases * 4), MCAI_Min(batch, 6), c_makePriorityAttack)) { return; }\n        }\n        if (gas >= 100 && MCAI_Ready(p, \"Starport\") > 0) {\n            if (MCAI_Train(p, town, \"Medivac\", MCAI_Min(16, bases * 3), MCAI_Min(batch, 6), c_makePriorityAttack)) { return; }\n        }\n        if (gas >= 60 && MCAI_Ready(p, \"BarracksTechLab\") > 0) {\n            if (MCAI_Train(p, town, \"Marauder\", MCAI_Min(48, bases * 10), MCAI_Min(batch, 6), c_makePriorityAttack)) { return; }\n        }\n        if (MCAI_Ready(p, \"Barracks\") > 0) { MCAI_Train(p, town, \"Marine\", goal, batch, c_makePriorityAttack); }\n    } else if (race == \"Prot\") {\n        if (air && gas >= 100 && MCAI_Ready(p, \"Stargate\") > 0) {\n            if (MCAI_Train(p, town, \"Phoenix\", MCAI_Min(24, bases * 5), MCAI_Min(batch, 4), c_makePriorityDefense)) { return; }\n        }\n        if (gas >= 180 && minerals >= 250 && (mcai_tick + p) % 3 == 0 && MCAI_Ready(p, \"Stargate\") > 0) {\n            if (MCAI_Train(p, town, \"VoidRay\", MCAI_Min(40, bases * 5), MCAI_Min(batch, 4), c_makePriorityAttack)) { return; }\n        }\n        if (!air && gas >= 120 && MCAI_Ready(p, \"RoboticsFacility\") > 0) {\n            if (MCAI_Train(p, town, \"Immortal\", MCAI_Min(22, bases * 4), MCAI_Min(batch, 6), c_makePriorityAttack)) { return; }\n        }\n        if (gas >= 50 && MCAI_Ready(p, \"CyberneticsCore\") > 0) {\n            if (MCAI_Train(p, town, \"Stalker\", MCAI_Min(220, 24 + bases * 28), MCAI_Min(batch, 6), c_makePriorityAttack)) { return; }\n        }\n        if (MCAI_Ready(p, \"Gateway\") > 0 || MCAI_Ready(p, \"WarpGate\") > 0) {\n            MCAI_Train(p, town, \"Zealot\", goal, batch, c_makePriorityAttack);\n        }\n    } else if (race == \"Zerg\") {\n        if (gas >= 120 && MCAI_Ready(p, \"HydraliskDen\") > 0) {\n            if (MCAI_Train(p, town, \"Hydralisk\", MCAI_Min(65, 8 + bases * 12), MCAI_Min(batch, 6), c_makePriorityAttack)) { return; }\n        }\n        if (!air && gas >= 70 && MCAI_Ready(p, \"RoachWarren\") > 0) {\n            if (MCAI_Train(p, town, \"Roach\", MCAI_Min(220, 24 + bases * 28), MCAI_Min(batch, 10), c_makePriorityAttack)) { return; }\n        }\n        if (MCAI_Ready(p, \"SpawningPool\") > 0) {\n            MCAI_Train(p, town, \"Zergling\", MCAI_Min(720, goal * 2), batch, c_makePriorityAttack);\n        }\n    }\n}\nvoid MCAI_Player(int p) {\n    string race;\n    int town;\n    int bases;\n    int minerals;\n    int gas;\n    fixed made;\n    fixed cap;\n    fixed free;\n    if (PlayerType(p) != c_playerTypeComputer || PlayerStatus(p) != c_playerStatusActive ||\n        AIIsCampaign(p) || AIGetTime() < 30.0) { return; }\n    town = AIGetMainTown(p);\n    if (town < 0 || AIGetTownState(p, town) != c_townStateEstablished) { return; }\n    race = PlayerRace(p);\n    if (race != \"Terr\" && race != \"Prot\" && race != \"Zerg\") { return; }\n    bases = MCAI_Max(1, AIGetNumEstablishedTowns(p));\n    minerals = PlayerGetPropertyInt(p, c_playerPropMinerals);\n    gas = PlayerGetPropertyInt(p, c_playerPropVespene);\n    made = PlayerGetPropertyFixed(p, c_playerPropSuppliesMade);\n    cap = PlayerGetPropertyFixed(p, c_playerPropSuppliesLimit);\n    free = made - PlayerGetPropertyFixed(p, c_playerPropSuppliesUsed);\n    if (made > cap) { free = cap - PlayerGetPropertyFixed(p, c_playerPropSuppliesUsed); }\n    if (minerals >= 600 || gas >= 600) { mcai_bankTicks[p] += 1; }\n    else { mcai_bankTicks[p] = 0; }\n    if (mcai_tick % 5 == 0) { MCAI_Configure(p, mcai_bankTicks[p] >= 3); }\n    MCAI_Economy(p, town, race, bases, minerals, gas, free, made, cap);\n    MCAI_Army(p, town, race, bases, minerals, gas, free);\n    if (mcai_debug && mcai_tick % 15 == 0) {\n        TriggerDebugOutput(1, StringToText(\"MiniAI p=\" + IntToString(p) + \" M=\" + IntToString(minerals) +\n            \" G=\" + IntToString(gas) + \" bases=\" + IntToString(bases) +\n            \" build=\" + IntToString(mcai_buildRequests[p]) + \" train=\" + IntToString(mcai_trainRequests[p]) +\n            \" expand=\" + IntToString(mcai_expandRequests[p])), true);\n    }\n}\nbool MCAI_Pulse(bool testConds, bool runActions) {\n    int p = 1;\n    if (!runActions) { return true; }\n    mcai_tick += 1;\n    while (p <= 15) {\n        MCAI_Player(p);\n        p += 1;\n    }\n    return true;\n}\nvoid MiniCraftAI_Init() {\n    if (mcai_timer != null) { return; }\n    mcai_timer = TriggerCreate(\"MCAI_Pulse\");\n    TriggerAddEventTimePeriodic(mcai_timer, 4.0, c_timeGame);\n    TriggerDebugOutput(1, StringToText(\"MiniCraft AI v0.1.10 initialized\"), true);\n}\n"
TOOLTIPS = {
    "Button/Tooltip/RavagerCorrosiveBile": '대상 지점에 투사체를 발사하여 떨어지는 지역의 모든 유닛에게 <d ref="Effect,RavagerCorrosiveBileDamage,Amount"/>의 피해를 줍니다.<n/><n/><c val="#ColorAttackInfo">프로토스 역장 파괴 가능</c>',
    "Button/Tooltip/ParasiticBomb": '대상과 주변 적 공중 유닛에게 지속 피해를 줍니다. 총 피해량은 순정의 10%를 목표로 합니다.<n/><n/><c val="#ColorAttackInfo">지상 유닛 및 구조물에는 사용할 수 없습니다.</c>',
}
def validate():
    parsed = {name: ET.fromstring(xml) for name, xml in CATALOGS.items()}
    for name, tree in parsed.items():
        ids = [n.get("id") for n in tree if n.get("id")]
        if len(ids) != len(set(ids)):
            raise ValueError("Duplicate catalog ID: " + name)
    checks = [
        ("EffectData", "AcidSalivaU", "Amount", "1.6"),
        ("EffectData", "RavagerWeaponDamage", "Amount", "1.6"),
        ("EffectData", "RavagerCorrosiveBileDamage", "Amount", "6"),
        ("EffectData", "ParasiticBombDotDamage", "Amount", "0.3"),
        ("EffectData", "LocustMPDamage", "Amount", "1"),
        ("EffectData", "NeedleClaws", "Amount", "0.4"),
        ("UnitData", "Egg", "LifeMax", "20"),
        ("UnitData", "LocustMP", "LifeMax", "5"),
        ("UnitData", "LocustMPFlying", "LifeMax", "5"),
        ("GameData", "Dflt", "DamageMinimum", "0.05"),
    ]
    for cat, uid, field, expected in checks:
        node = parsed[cat].find("./*[@id='" + uid + "']/" + field)
        if node is None or node.get("value") != expected:
            raise ValueError("Regression check failed: " + uid + "/" + field)
    for uid in ("Overlord", "LocustMP", "LocustMPFlying"):
        node = parsed["ActorData"].find("./*[@id='" + uid + "']/Scale")
        if node is None:
            raise ValueError("Missing scale: " + uid)
    for resource in ("Minerals", "Vespene"):
        values = [parsed["UnitData"].find("./*[@id='" + uid + "']/CostResource[@index='" + resource + "']").get("value") for uid in ("Overseer", "OverseerSiegeMode")]
        if values[0] != values[1]:
            raise ValueError("Overseer mode cost mismatch")
    for uid, size in (("MiniFootprint5x5Contour", 3), ("MiniFootprint3x3Contour", 2), ("MiniFootprint2x2Contour", 1)):
        rows = parsed["FootprintData"].findall("./*[@id='" + uid + "']/Layers[@index='Place']/Rows")
        if len(rows) != size or any(row.get("value") != "x" * size for row in rows):
            raise ValueError("Footprint check failed: " + uid)
    additional_checks = [
        ("EffectData", "PsiStormDamage", "<Amount value=\"0.625\"/>"),
        ("EffectData", "NukeDamage", "<Amount value=\"30\"/>"),
        ("EffectData", "RavagerCorrosiveBileDamage", "<Amount value=\"6\"/>"),
        ("EffectData", "ParasiticBombDotDamage", "<Amount value=\"0.3\"/>"),
        ("EffectData", "EMPModifyUnit", "<Change value=\"-10\"/>"),
        ("BehaviorData", "ImmortalOverload", "ModifyLimit=\"10\""),
        ("BehaviorData", "GuardianShield", "<ModifyAmount value=\"-0.2\"/>"),
        ("AbilData", "ProtossBuild", "index=\"Build16\" Time=\"20\""),
        ("AbilData", "TrainQueen", "index=\"Train1\" Time=\"25\""),
        ("AbilData", "MorphToRavager", "index=\"Delay\" value=\"8.5\""),
        ("AbilData", "CarrierHangar", "index=\"Ammo1\" Time=\"6\""),
        ("UnitData", "BarracksTechLab", "MiniFootprint2x2Contour"),
        ("UnitData", "InfestedTerransEgg", "<LifeMax value=\"7.5\"/>"),
    ]
    for cat, uid, expected in additional_checks:
        node = parsed[cat].find("./*[@id='" + uid + "']")
        if node is None:
            raise ValueError("Missing audit entry: " + uid)
        raw = ET.tostring(node, encoding="unicode").replace(" />", "/>")
        if expected not in raw:
            raise ValueError("Audit regression: " + uid)
    model_checks = [
        ("Nexus", "ScaleMin", "0.6,0.6,0.6"),
        ("Nexus", "ShadowRadius", "0.624925"),
        ("NexusPlacement", "ScaleMin", "0.6,0.6,0.6"),
        ("NexusBirth", "ScaleMin", "0.6,0.6,0.6"),
        ("NexusSplat", "ScaleMin", "0.6,0.6,0.6"),
        ("GatewayPlacement", "ScaleMin", "0.4,0.4,0.4"),
        ("PylonPlacement", "ScaleMin", "0.425,0.425,0.425"),
    ]
    for uid, field, expected in model_checks:
        node = parsed["ModelData"].find("./*[@id='" + uid + "']/" + field)
        if node is None or node.get("value") != expected:
            raise ValueError("Model regression: " + uid + "/" + field)
    for uid in ("Nexus", "Gateway", "Pylon", "Barracks", "Hatchery"):
        if parsed["ActorData"].find("./*[@id='" + uid + "']/Scale") is not None:
            raise ValueError("Duplicate visual scaling: " + uid)
    for uid in ("Refinery", "RefineryRich", "Assimilator", "AssimilatorRich", "Extractor", "ExtractorRich"):
        for field in ("Radius", "SeparationRadius"):
            assert parsed["UnitData"].find(f"./*[@id='{uid}']/{field}").get("value") == "1.5", uid
    for uid in ("Probe", "Zealot", "Stalker", "Nexus", "ShieldBattery"):
        assert parsed["UnitData"].find(f"./*[@id='{uid}']/ShieldRegenRate").get("value") == "0.2", uid
    for uid in ("ShieldBatteryRechargeChanneled", "ShieldBatteryRechargeEx5"):
        assert parsed["EffectData"].find(f"./*[@id='{uid}']/DrainVitalCostFactor").get("value") == "3.3", uid
        assert parsed["AbilData"].find(f"./*[@id='{uid}']/Range").get("value") == "4", uid
    for uid in ("BroodLord", "LurkerMP"):
        assert parsed["ActorData"].find(f"./*[@id='{uid}']/Scale") is not None, uid
    for uid in ("StalkerPlacement", "StalkerWarpIn", "BroodLordDeath", "BroodLordDeathRagdoll"):
        assert parsed["ModelData"].find(f"./*[@id='{uid}']/ScaleMin") is not None, uid
    for uid in ("Repair", "MULERepair"):
        assert parsed["EffectData"].find(f"./*[@id='{uid}']/RechargeVitalRate").get("value") == "0.1", uid
    for uid in ("MedivacHeal", "RavenRepairDroneHeal", "ShieldHeal"):
        assert parsed["EffectData"].find(f"./*[@id='{uid}']/DrainVitalCostFactor").get("value") == "3.3", uid
    assert "void MiniCraftAI_Init()" in AI_SOURCE
    assert "TriggerAddEventTimePeriodic" in AI_SOURCE
    assert "AISetStockArmyDefaultScale" in AI_SOURCE
    print("Static regression checks passed.")
def merge_strings(data, changes):
    old = data.decode("utf-8-sig").splitlines() if data else []
    keys = set(changes)
    lines = [line for line in old if line.split("=", 1)[0] not in keys]
    lines.extend(k + "=" + v for k, v in changes.items())
    return ("\r\n".join(lines) + "\r\n").encode("utf-8-sig")
def includes_for(existing=None):
    tree = ET.fromstring(existing) if existing else ET.Element("Includes")
    if tree.tag != "Includes":
        raise ValueError("Unexpected GameData.xml structure")
    paths = {n.get("path", "").replace("\\", "/").lower() for n in tree if n.tag == "Catalog"}
    for name in CATALOGS:
        path = "GameData/" + name + ".xml"
        if path.lower() not in paths:
            ET.SubElement(tree, "Catalog", {"path": path})
    return ET.tostring(tree, encoding="utf-8", xml_declaration=True)
def main():
    validate()
    if "--check" in sys.argv:
        return
    home = Path(os.environ.get("MINICRAFT_HOME", str(Path(__file__).resolve().parent))).resolve()
    target_file = Path(os.environ["MINICRAFT_TARGET_FILE"]) if os.environ.get("MINICRAFT_TARGET_FILE") else None
    explicit = len(sys.argv) > 1
    if explicit:
        root = Path(sys.argv[1]).expanduser().resolve()
    elif target_file and target_file.is_file():
        root = Path(target_file.read_text(encoding="utf-8").strip()).expanduser().resolve()
        if not root.is_dir():
            raise SystemExit("Remembered mod folder is missing. Drop the correct folder onto the BAT.")
    else:
        root = home / "MiniCraft-II.SC2Mod"
    patch = explicit or root.exists()
    print("Target:", root)
    if patch:
        if not root.is_dir() or not (root / "ComponentList.SC2Components").is_file():
            raise SystemExit("Select the existing MiniCraft component folder, not a packed SC2Mod file.")
        # Native component layout verified against TeamKoprulu/SCEvoComplete
        # SC2_5015_Balance.SC2Mod: standard catalogs need no root Includes file.
        data_dir = root / "Base.SC2Data" / "GameData"
        if not data_dir.is_dir():
            raise SystemExit("Missing Base.SC2Data/GameData directory; save as component files in Galaxy Editor.")
        payload = {}
        # Preserve any existing root manifest byte-for-byte. Custom includes
        # are distinct from standard catalog filenames and must not be invented.
        strings = root / "koKR.SC2Data/LocalizedData/GameStrings.txt"
        if strings.is_file():
            payload["koKR.SC2Data/LocalizedData/GameStrings.txt"] = merge_strings(strings.read_bytes(), TOOLTIPS)
        backup = root.with_name(root.name + ".backup-" + datetime.now().strftime("%Y%m%d-%H%M%S-%f"))
        shutil.copytree(root, backup)
        print("Backup:", backup)
    else:
        if root.exists():
            raise SystemExit("Output already exists. Rename it before rebuilding; no files overwritten.")
        payload = {path: base64.b64decode(value, validate=True) for path, value in METADATA.items()}
        key = "koKR.SC2Data/LocalizedData/GameStrings.txt"
        payload[key] = merge_strings(payload.get(key, b""), {
            "DocInfo/Name": "URZ MiniCraft II",
            "DocInfo/DescShort": "소형 유닛 대규모 물량전",
            "DocInfo/DescLong": "유닛과 건물을 축소하고 생산을 가속하는 섬멸전 확장 모드입니다.",
            **TOOLTIPS,
        })
    for name, xml in CATALOGS.items():
        relative = "Base.SC2Data/GameData/" + name + ".xml"
        if patch and name == "GameData" and (root / relative).is_file():
            # Preserve custom CGame fields, especially native TriggerLibs.
            current = ET.fromstring((root / relative).read_bytes())
            if current.tag != "Catalog":
                raise SystemExit("Unexpected nested GameData.xml: expected Catalog")
            for change in ET.fromstring(xml):
                target = next((node for node in current if node.tag == change.tag and node.get("id") == change.get("id")), None)
                if target is None:
                    current.append(change)
                    continue
                for field in change:
                    for previous in list(target):
                        if previous.tag == field.tag and previous.get("index") == field.get("index"):
                            target.remove(previous)
                    target.append(field)
            payload[relative] = ET.tostring(current, encoding="utf-8", xml_declaration=True)
        else:
            payload[relative] = xml.encode("utf-8")
    # The raw Galaxy source is maintained by the builder, but deliberately does not
    # overwrite the user's existing Triggers or trigger library initialization.
    payload["Base.SC2Data/TriggerLibs/MiniCraftAI.galaxy"] = AI_SOURCE.encode("utf-8")
    for path, data in payload.items():
        dest = root / path
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_bytes(data)
    if target_file:
        target_file.parent.mkdir(parents=True, exist_ok=True)
        pending = target_file.with_suffix(".tmp")
        pending.write_text(str(root), encoding="utf-8")
        pending.replace(target_file)
    print("Created or patched:", root)
    print("AI source exported: Base.SC2Data/TriggerLibs/MiniCraftAI.galaxy")
    print("AI requires one-time trigger-library initialization: MiniCraftAI_Init()")
    print("Open the component folder in Galaxy Editor. Native editor and game not verified.")
if __name__ == "__main__":
    main()
